Вот реализация связанного списка на Go с использованием дженериков и методов по добавлению/удалению/получению элементов. Мы будем использовать `any` для поддержки дженериков, но в реальном проекте лучше использовать `interface{}` или более конкретные интерфейсы.

```go
package linkedlist

import (
	"fmt"
)

// Node represents a single element in the linked list.
type Node[T any] struct {
	Value T
	Next  *Node[T]
}

// LinkedList is a doubly-linked list implementation with generic support.
type LinkedList[T any] struct {
	Head   *Node[T]
	Tail   *Node[T]
	Length int
}

// New creates a new empty linked list.
func New[T any]() *LinkedList[T] {
	return &LinkedList[T]{}
}

// Append adds a new node to the end of the list.
func (ll *LinkedList[T]) Append(value T) {
	newNode := &Node[T]{Value: value, Next: nil}

	if ll.Length == 0 {
		ll.Head = newNode
	} else {
		ll.Tail.Next = newNode
	}
	ll.Tail = newNode
	ll.Length++
}

// Prepend adds a new node to the beginning of the list.
func (ll *LinkedList[T]) Prepend(value T) {
	newNode := &Node[T]{Value: value, Next: nil}

	if ll.Length == 0 {
		ll.Head = newNode
	} else {
		newNode.Next = ll.Head
	}
	ll.Head = newNode
	ll.Length++
}

// Delete removes the first occurrence of a value from the list.
func (ll *LinkedList[T]) Delete(value T) bool {
	if ll.Length == 0 {
		return false
	}

	var prev, current *Node[T]
	current = ll.Head

	for current != nil && !eq(current.Value, value) {
		prev = current
		current = current.Next
	}

	if current == nil {
		return false // Value not found
	}

	if prev == nil { // Deleting the head
		ll.Head = current.Next
	} else {
		prev.Next = current.Next
	}

	// If we deleted the tail, update it
	if ll.Tail.Value == value && ll.Length > 1 {
		ll.Tail = prev
	}
	ll.Length--
	return true
}

// eq is a helper function to compare values of any type.
func eq[T any](a, b T) bool {
	switch any(a).(type) {
	case nil:
		return b == nil
	default:
		return fmt.Sprintf("%v", a) == fmt.Sprintf("%v", b)
	}
}

// Get returns the value at the given index (0-based).
func (ll *LinkedList[T]) Get(index int) (T, bool) {
	if index < 0 || index >= ll.Length {
		var zero T
		return zero, false
	}

	current := ll.Head
	for i := 0; i < index; i++ {
		current = current.Next
	}
	return current.Value, true
}

// Print displays the list contents.
func (ll *LinkedList[T]) Print() {
	current := ll.Head
	for current != nil {
		fmt.Printf("%v -> ", current.Value)
		current = current.Next
	}
	fmt.Println("nil")
}
```

### Примеры использования:
```go
// Создаем список целых чисел
intList := linkedlist.New[int]()
intList.Append(10)
intList.Append(20)
intList.Prepend(5)
fmt.Println("Список:")
intList.Print() // Вывод: 5 -> 10 -> 20 -> nil

// Удаляем элемент
intList.Delete(10)
fmt.Println("\nПосле удаления:")
intList.Print() // Вывод: 5 -> 20 -> nil

// Получаем элемент по индексу
value, ok := intList.Get(1)
if ok {
	fmt.Printf("Элемент на позиции 1: %v\n", value) // Вывод: 20
}
```

### Ключевые моменты:
1. **Дженерики**: Используем `Node[T]` и `LinkedList[T]` для поддержки любых типов данных.
2. **Методы**: Обеспечиваем полный набор операций: добавление в начало/конец, удаление, получение по индексу.
3. **Двойная связность**: Храним указатели как на `Head`, так и на `Tail` для удобства работы с концами списка.
4. **Сравнение значений**: Используем вспомогательную функцию `eq` для сравнения элементов любого типа.

### Вопросы для самопроверки:
1. Как будет выглядеть реализация для структур, если мы хотим использовать их как значения в списке?
2. Почему мы не храним указатель на предыдущий элемент (`Prev`) в узлах? (Подсказка: это делает список односторонним.)
3. Какие ограничения есть у этой реализации по сравнению с массивом или слайсом?

